import React from 'react';

function LandingHeader() {
  return (
    <header className="w-full h-20 bg-gray-800 flex items-center justify-between px-8">
      {/* Логотип */}
      <div className="text-white text-2xl font-bold">CarChase</div>

      {/* Навигация */}
      <nav className="hidden md:flex space-x-6">
        <a href="#about" className="text-white hover:text-gray-400">About</a>
        <a href="#services" className="text-white hover:text-gray-400">Services</a>
        <a href="#contact" className="text-white hover:text-gray-400">Contact</a>
        <a href="#blog" className="text-white hover:text-gray-400">Blog</a>
      </nav>

      {/* Кнопка */}
      <button className="bg-blue-700 text-white px-4 py-2 rounded-md hover:bg-blue-600 transition">
        Get Started
      </button>
    </header>
  );
}

export default LandingHeader;
